import React, { useState } from 'react';
import { Link } from 'react-router-dom';
import { Plus, ExternalLink, ArrowRight, FolderOpen, Search, Filter, X } from 'lucide-react';
import { Project } from '../types';
import { INITIAL_PROJECTS } from '../constants';

const Portfolio: React.FC = () => {
  const [projects, setProjects] = useState<Project[]>(INITIAL_PROJECTS);
  const [filter, setFilter] = useState<'All' | 'Web' | 'App' | 'Graphics'>('All');
  const [showUploader, setShowUploader] = useState(false);

  // Mock uploader state
  const [newTitle, setNewTitle] = useState('');
  const [newCat, setNewCat] = useState<'Web' | 'App' | 'Graphics'>('Web');
  const [newUrl, setNewUrl] = useState('');

  const handleAddProject = (e: React.FormEvent) => {
    e.preventDefault();
    const newProject: Project = {
      id: Date.now().toString(),
      title: newTitle || 'Untitled Project',
      category: newCat,
      imageUrl: newUrl || `https://picsum.photos/seed/${Date.now()}/800/600`,
      link: '#',
      description: 'A newly added amazing project by Cloud One Technologies.'
    };
    setProjects([newProject, ...projects]);
    setShowUploader(false);
    setNewTitle('');
    setNewUrl('');
  };

  const filteredProjects = filter === 'All' ? projects : projects.filter(p => p.category === filter);

  return (
    <div className="bg-[#F8FAFC] min-h-screen py-8 md:py-16 p-4">
      <div className="max-w-7xl mx-auto md:px-8">
        <div className="flex flex-col md:flex-row justify-between items-center mb-12 gap-6">
          <div className="text-center md:text-left">
            <h1 className="text-4xl md:text-5xl font-black text-gray-900 tracking-tight">Our Portfolio</h1>
            <p className="text-gray-500 font-medium mt-2">Transforming ideas into digital reality</p>
          </div>

          <button
            onClick={() => setShowUploader(!showUploader)}
            className="flex items-center px-6 py-3 bg-blue-600 text-white font-bold rounded-2xl hover:bg-blue-700 transition-all shadow-xl shadow-blue-100 active:scale-95"
          >
            {showUploader ? <X className="w-5 h-5 mr-2" /> : <Plus className="w-5 h-5 mr-2" />}
            {showUploader ? 'Cancel Upload' : 'Add New Work'}
          </button>
        </div>

        {/* Filters Sticky or Scrolled */}
        <div className="flex items-center gap-3 overflow-x-auto no-scrollbar pb-6 mb-8">
          <div className="p-2 bg-white rounded-xl shadow-sm mr-2 shrink-0">
             <Filter size={20} className="text-gray-400" />
          </div>
          {['All', 'Web', 'App', 'Graphics'].map((cat) => (
            <button
              key={cat}
              onClick={() => setFilter(cat as any)}
              className={`px-6 py-2.5 rounded-2xl text-sm font-bold transition-all shrink-0 active:scale-95 ${
                filter === cat ? 'bg-blue-600 text-white shadow-lg' : 'bg-white text-gray-600 border border-gray-100 hover:bg-gray-50'
              }`}
            >
              {cat}
            </button>
          ))}
        </div>

        {/* Upload Form - Drawer/Card Feel */}
        {showUploader && (
          <div className="mb-12 p-8 bg-white rounded-[32px] shadow-2xl border border-blue-50 animate-in fade-in slide-in-from-top-4 duration-300">
            <h2 className="text-2xl font-bold mb-8 flex items-center">
              <FolderOpen className="mr-3 text-blue-600" />
              Upload Project Meta
            </h2>
            <form onSubmit={handleAddProject} className="grid grid-cols-1 md:grid-cols-3 gap-6">
              <div className="space-y-2">
                <label className="text-xs font-black uppercase tracking-widest text-gray-400">Project Title</label>
                <input
                  type="text"
                  required
                  placeholder="e.g. Dubai Luxury Real Estate"
                  className="w-full px-5 py-4 rounded-2xl border border-gray-100 bg-gray-50 focus:bg-white focus:ring-2 focus:ring-blue-500/20 outline-none transition-all font-medium"
                  value={newTitle}
                  onChange={(e) => setNewTitle(e.target.value)}
                />
              </div>
              <div className="space-y-2">
                <label className="text-xs font-black uppercase tracking-widest text-gray-400">Category</label>
                <select
                  className="w-full px-5 py-4 rounded-2xl border border-gray-100 bg-gray-50 focus:bg-white focus:ring-2 focus:ring-blue-500/20 outline-none transition-all font-medium appearance-none"
                  value={newCat}
                  onChange={(e) => setNewCat(e.target.value as any)}
                >
                  <option value="Web">Web Development</option>
                  <option value="App">Mobile App Design</option>
                  <option value="Graphics">Graphics & Branding</option>
                </select>
              </div>
              <div className="space-y-2">
                <label className="text-xs font-black uppercase tracking-widest text-gray-400">Image Source</label>
                <input
                  type="text"
                  placeholder="Direct image URL..."
                  className="w-full px-5 py-4 rounded-2xl border border-gray-100 bg-gray-50 focus:bg-white focus:ring-2 focus:ring-blue-500/20 outline-none transition-all font-medium"
                  value={newUrl}
                  onChange={(e) => setNewUrl(e.target.value)}
                />
              </div>
              <div className="md:col-span-3 flex justify-end mt-4">
                <button
                  type="submit"
                  className="w-full md:w-auto px-12 py-4 bg-blue-600 text-white font-bold rounded-2xl shadow-xl shadow-blue-200 hover:bg-blue-700 transition-all active:scale-95"
                >
                  Confirm Upload
                </button>
              </div>
            </form>
          </div>
        )}

        {/* Project Grid */}
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8">
          {filteredProjects.map((project) => (
            <div key={project.id} className="app-card bg-white overflow-hidden shadow-sm hover:shadow-2xl transition-all duration-500 group flex flex-col h-full border border-gray-100/30">
              <div className="relative overflow-hidden aspect-[4/5]">
                <img
                  src={project.imageUrl}
                  alt={project.title}
                  className="w-full h-full object-cover group-hover:scale-110 transition-transform duration-1000 ease-out"
                />

                <div className="absolute inset-0 bg-blue-900/40 opacity-0 group-hover:opacity-100 transition-opacity duration-500 pointer-events-none flex items-center justify-center">
                   <div className="w-16 h-16 bg-white rounded-full flex items-center justify-center scale-50 group-hover:scale-100 transition-all duration-500 shadow-2xl">
                      <Search className="w-6 h-6 text-blue-600" />
                   </div>
                </div>

                <div className="absolute top-6 left-6 z-10">
                  <span className="px-5 py-2 bg-white/95 backdrop-blur-md rounded-full text-[10px] font-black text-blue-600 shadow-lg uppercase tracking-[0.2em]">
                    {project.category}
                  </span>
                </div>
              </div>
              <div className="p-8 flex flex-col flex-grow">
                <h3 className="text-2xl font-black text-gray-900 mb-3">{project.title}</h3>
                <p className="text-gray-500 text-sm font-medium leading-relaxed flex-grow line-clamp-3">{project.description}</p>
                <div className="pt-6 mt-6 border-t border-gray-50 flex justify-between items-center">
                  <a
                    href={project.link}
                    className="inline-flex items-center text-blue-600 font-bold hover:text-blue-700 transition-all text-sm group/btn"
                  >
                    Launch Project
                    <ExternalLink className="ml-2 w-4 h-4 transform group-hover/btn:translate-x-1 transition-transform" />
                  </a>
                </div>
              </div>
            </div>
          ))}
        </div>

        {filteredProjects.length === 0 && (
          <div className="text-center py-24 bg-white rounded-[40px] border-2 border-dashed border-gray-100">
            <FolderOpen size={48} className="mx-auto text-gray-200 mb-4" />
            <p className="text-lg text-gray-400 font-bold">No projects matching this filter</p>
            <button onClick={() => setFilter('All')} className="mt-4 text-blue-600 font-black text-sm uppercase tracking-widest">Reset Filters</button>
          </div>
        )}

        {/* CTA */}
        <div className="mt-24 text-center">
           <div className="bg-white rounded-[40px] p-12 md:p-16 shadow-2xl shadow-blue-50/50 border border-white">
              <h2 className="text-3xl md:text-5xl font-black text-gray-900 mb-6 leading-tight">Your project could be <br /> our next success story.</h2>
              <p className="text-gray-500 font-medium mb-12 max-w-xl mx-auto">Join the leading brands in the UAE working with Cloud One Technologies to innovate and scale.</p>
              <Link
                to="/contact"
                className="inline-flex items-center px-12 py-5 bg-blue-600 text-white font-black rounded-2xl shadow-xl shadow-blue-100 hover:bg-blue-700 transition-all transform hover:-translate-y-1 active:scale-95 uppercase tracking-widest text-sm"
              >
                Let's Build It
                <ArrowRight className="ml-3 w-5 h-5" />
              </Link>
           </div>
        </div>
      </div>
    </div>
  );
};

export default Portfolio;

