          <NavLink
            key={to}
            to={to}
            className={({ isActive }) =>
              `flex flex-col items-center gap-1.5 transition-all duration-300 relative ${
                isActive ? 'text-blue-600 scale-110' : 'text-gray-400 hover:text-gray-500'
