                  )}
                </Link>

                {/* Desktop Dropdown */}
                {link.hasDropdown && (
                  <div className={`absolute top-full left-0 pt-4 transition-all duration-300 ${servicesOpen ? 'opacity-100 translate-y-0 pointer-events-auto' : 'opacity-0 -translate-y-4 pointer-events-none'}`}>
